	jr nz, .x43F7                   ; 43EC
	inc hl                          ; 43EE
	ld a, [wSndArgB]                ; 43EF
	cp [hl]                         ; 43F2
	jr nz, .x43F7                   ; 43F3
	xor a                           ; 43F5
	ld [bc], a                      ; 43F6
.x43F7
	call IterTracksNext             ; 43F7
	jr nz, .x43D7                   ; 43FA
	jp Snd_Exit                     ; 43FC
StopAllSfx:
	call IterSfxTracks              ; 43FF
.x4402
	ld a, [wCurTrack]               ; 4402
	ld l, a                         ; 4405
	ld a, [wCurTrack+1]             ; 4406
	ld h, a                         ; 4409
	xor a                           ; 440A
	ld [hl], a                      ; 440B
	call IterTracksNext             ; 440C
	jr nz, .x4402                   ; 440F
	jp Snd_Exit                     ; 4411

; API $3F24: pause the music tracks (they can be resumed)
; (called through Sound_StopMusic)
SndImpl_StopMusic::
	call PauseMusicTracks           ; 4414
	jp Snd_Exit                     ; 4417
FadeDone:
	xor a                           ; 441A
	ld [wFadeSpeed], a              ; 441B
PauseMusicTracks:
	ld a, $FF                       ; 441E
	ld [wMusicPaused], a            ; 4420
	call IterMusicTracks            ; 4423
.x4426
	ld a, [wCurTrack]               ; 4426
	ld l, a                         ; 4429
	ld a, [wCurTrack+1]             ; 442A
	ld h, a                         ; 442D
	res 7, [hl]                     ; 442E
	call IterTracksNext             ; 4430
	jr nz, .x4426                   ; 4433
	ret                             ; 4435

; API $3F30: d = active SFX slot mask, e = active music slot mask
; (called through Sound_GetActive)
SndImpl_GetActive::
	ld a, [wActiveMask]             ; 4436
	and $0F                         ; 4439
	ld d, a                         ; 443B
	ld a, [wActiveMask]             ; 443C
	and $F0                         ; 443F
	swap a                          ; 4441
	ld e, a                         ; 4443
	jp Snd_Exit                     ; 4444

; API $3F42: a = 0: bc = current music id (0 if none active); a = 1-4: bc = id in SFX slot a
; (called through Sound_Query)
SndImpl_Query::
	and a                           ; 4447
	jr nz, .x445B                   ; 4448
	ld a, [wActiveMask]             ; 444A
	and $F0                         ; 444D
	jr z, .x445F                    ; 444F
	ld a, [wMusicId]                ; 4451
	ld c, a                         ; 4454
	ld a, [wMusicId+1]              ; 4455
	ld b, a                         ; 4458
	jr .x4483                       ; 4459
.x445B
	cp $05                          ; 445B
	jr c, .x4464                    ; 445D
.x445F
	ld bc, $0000                    ; 445F
	jr .x4483                       ; 4462
.x4464
	ld bc, SfxSlotPtrs - 2          ; 4464
	sla a                           ; 4467
	add a, c                        ; 4469
	ld c, a                         ; 446A
	ld a, $00                       ; 446B
	adc a, b                        ; 446D
	ld b, a                         ; 446E
	ld a, [bc]                      ; 446F
	ld l, a                         ; 4470
	inc bc                          ; 4471
	ld a, [bc]                      ; 4472
	ld h, a                         ; 4473
	ld bc, $0000                    ; 4474
	bit 7, [hl]                     ; 4477
	jr z, .x4483                    ; 4479
	ld bc, $0005                    ; 447B
	add hl, bc                      ; 447E
	ld a, [hl+]                     ; 447F
	ld c, a                         ; 4480
	ld a, [hl+]                     ; 4481
	ld b, a                         ; 4482
.x4483
	jp Snd_Exit                     ; 4483

SfxSlotPtrs:
	dw wTracks
	dw wTracks + 1*TRK_SIZE
	dw wTracks + 2*TRK_SIZE
	dw wTracks + 3*TRK_SIZE

; API $3F36: a = parameter 0-6, bc = value, d/e = SFX/music track masks
; (called through Sound_SetParam)
SndImpl_SetParam::
	call SetParam                   ; 448E
	jp Snd_Exit                     ; 4491
SetParam:
	cp $07                          ; 4494
	ret nc                          ; 4496
	push af                         ; 4497
	ld hl, wSndArgA                 ; 4498
	ld a, c                         ; 449B
	ld [hl+], a                     ; 449C
	ld a, b                         ; 449D
	ld [hl+], a                     ; 449E
	ld a, e                         ; 449F
	ld [hl+], a                     ; 44A0
	ld a, d                         ; 44A1
	ld [hl+], a                     ; 44A2
	xor a                           ; 44A3
	ld [hl], a                      ; 44A4
	pop af                          ; 44A5
	ld bc, ParamTable               ; 44A6
	jp JumpTable                    ; 44A9

ParamTable:
	dw Param_TempoScale
	dw Param_PitchOffset
	dw Param_VolumeScale
	dw Param_PanOffset
	dw Param_LfoDepth
	dw Param_LfoSpeed
	dw Param_Echo

; for each selected track: TRK+bc = wSndArgB, flags |= wSndArgE
SetTrackByte:
	call GetParamMask               ; 44BA
.x44BD
	rrc d                           ; 44BD
	jr nc, .x44D1                   ; 44BF
	bit 7, [hl]                     ; 44C1
	jr z, .x44D1                    ; 44C3
	ld a, [wSndArgE]                ; 44C5
	or [hl]                         ; 44C8
	ld [hl], a                      ; 44C9
	push hl                         ; 44CA
	add hl, bc                      ; 44CB
	ld a, [wSndArgB]                ; 44CC
	ld [hl], a                      ; 44CF
	pop hl                          ; 44D0
.x44D1
	call NextParamTrack             ; 44D1
	jr nz, .x44BD                   ; 44D4
	ret                             ; 44D6

; for each selected track: TRK+bc = wSndArgA/wSndArgB, flags |= wSndArgE
SetTrackWord:
	call GetParamMask               ; 44D7
.x44DA
	rrc d                           ; 44DA
	jr nc, .x44F2                   ; 44DC
	bit 7, [hl]                     ; 44DE
	jr z, .x44F2                    ; 44E0
	ld a, [wSndArgE]                ; 44E2
	or [hl]                         ; 44E5
	ld [hl], a                      ; 44E6
	push hl                         ; 44E7
	add hl, bc                      ; 44E8
	ld a, [wSndArgA]                ; 44E9
	ld [hl+], a                     ; 44EC
	ld a, [wSndArgB]                ; 44ED
	ld [hl-], a                     ; 44F0
	pop hl                          ; 44F1
.x44F2
	call NextParamTrack             ; 44F2
	jr nz, .x44DA                   ; 44F5
	ret                             ; 44F7

; d = music mask << 4 | SFX mask, e = 8, hl = first track
GetParamMask:
	ld a, [wSndArgD]                ; 44F8
	and $0F                         ; 44FB
	ld d, a                         ; 44FD
	ld a, [wSndArgC]                ; 44FE
	swap a                          ; 4501
	and $F0                         ; 4503
	or d                            ; 4505
	ld d, a                         ; 4506
	ld e, $08                       ; 4507
	ld hl, wTracks                  ; 4509
	ret                             ; 450C
NextParamTrack:
	ld a, $3C                       ; 450D
	add a, l                        ; 450F
	ld l, a                         ; 4510
	ld a, $00                       ; 4511
	adc a, h                        ; 4513
	ld h, a                         ; 4514
	dec e                           ; 4515
	ret                             ; 4516

; API $3F3C: a = frames per step, music volume scale $40 -> 0 in steps of 4
; (called through Sound_FadeOut)
SndImpl_FadeOut::
	ld [wFadeSpeed], a              ; 4517
	ld [wFadeTimer], a              ; 451A
	ld a, $40                       ; 451D
	ld [wFadeLevel], a              ; 451F
	jp Snd_Exit                     ; 4522
UpdateFade:
	ld a, [wMusicPaused]            ; 4525
	and a                           ; 4528
	ret z                           ; 4529  BUG: returns while the music is NOT paused, so the fade never runs (no game code calls Sound_FadeOut)
	ld a, [wFadeSpeed]              ; 452A
	and a                           ; 452D
	ret z                           ; 452E
	ld hl, wFadeTimer               ; 452F
	dec [hl]                        ; 4532
	ret nz                          ; 4533
	ld [hl+], a                     ; 4534
	ld a, [hl]                      ; 4535
	sub $04                         ; 4536
	jp c, FadeDone                  ; 4538
	ld [hl], a                      ; 453B
	ld b, a                         ; 453C
	ld a, $02                       ; 453D
	ld de, $00FF                    ; 453F
	jp SetParam                     ; 4542

; frame without a tick: apply parameter changes only
TrackRefresh:
	ld a, [wCurTrack]               ; 4545
	ld l, a                         ; 4548
	ld a, [wCurTrack+1]             ; 4549
	ld h, a                         ; 454C
	ld a, [hl]                      ; 454D
	cp $C0                          ; 454E
	ret c                           ; 4550
	ld [wTrackFlags], a             ; 4551
