; one sequencer tick for wCurTrack
TrackTick:
	ld a, [wCurTrack]               ; 4557
	ld l, a                         ; 455A
	ld a, [wCurTrack+1]             ; 455B
	ld h, a                         ; 455E
	ld a, [hl]                      ; 455F
	bit 7, a                        ; 4560
	ret z                           ; 4562
	bit 6, a                        ; 4563
	jr nz, .x456D                   ; 4565
	push hl                         ; 4567
	call StartTrack                 ; 4568
	pop hl                          ; 456B
	ld a, [hl]                      ; 456C
.x456D
	ld [wTrackFlags], a             ; 456D
	inc hl                          ; 4570
	ld a, [hl]                      ; 4571
	and a                           ; 4572
	jr z, .x4579                    ; 4573
	dec [hl]                        ; 4575
	inc hl                          ; 4576
	jr TrackLfo                     ; 4577
.x4579
	inc hl                          ; 4579
	ld a, [hl+]                     ; 457A
	ld e, a                         ; 457B
	ld a, [hl+]                     ; 457C
	ld d, a                         ; 457D
	ld a, [hl]                      ; 457E
	ld [wSndBank], a                ; 457F

; read the next command (running status for bytes < $80)
ReadCommand:
	ld a, [wCurTrack]               ; 4582
	ld l, a                         ; 4585
	ld a, [wCurTrack+1]             ; 4586
	ld h, a                         ; 4589
	ld bc, TRK_STATUS               ; 458A
	add hl, bc                      ; 458D
