	jr nz, .x459D                   ; 4593
	ld a, c                         ; 4595
	ld [wCmdParam], a               ; 4596
	dec de                          ; 4599
	ld a, [hl]                      ; 459A
	jr .x45A7                       ; 459B
.x459D
	ld a, b                         ; 459D
	ld [wCmdParam], a               ; 459E
	ld a, c                         ; 45A1
	cp $BE                          ; 45A2  only $BE-$FF become the running status
	jr c, .x45A7                    ; 45A4
	ld [hl], a                      ; 45A6
.x45A7
	cp $D0                          ; 45A7
