; jump to table bc entry a
JumpTable:
	sla a                           ; 45B4
	add a, c                        ; 45B6
	ld c, a                         ; 45B7
	ld a, $00                       ; 45B8
	adc a, b                        ; 45BA
	ld b, a                         ; 45BB
	ld a, [bc]                      ; 45BC
	ld l, a                         ; 45BD
	inc bc                          ; 45BE
	ld a, [bc]                      ; 45BF
	ld h, a                         ; 45C0
	jp hl                           ; 45C1

; $B1 (and undefined commands): free the track
Cmd_End:
	ld a, [wCurTrack]               ; 45C2
	ld l, a                         ; 45C5
	ld a, [wCurTrack+1]             ; 45C6
	ld h, a                         ; 45C9
	xor a                           ; 45CA
