.x45DE
	ld bc, $FFF3                    ; 45DE
	add hl, bc                      ; 45E1
	ld a, [hl+]                     ; 45E2
	add a, [hl]                     ; 45E3
.x45E4
	ld [hl], a                      ; 45E4
