	jr z, .x4612                    ; 45F3
	ld c, a                         ; 45F5
	ld a, [wLfoValue]               ; 45F6
	ld b, a                         ; 45F9
	push hl                         ; 45FA
	push bc                         ; 45FB
	call Mul8                       ; 45FC
	pop bc                          ; 45FF
	ld b, h                         ; 4600
	pop hl                          ; 4601
	inc hl                          ; 4602
	ld a, [hl+]                     ; 4603
	cp $00                          ; 4604
	jr z, .x4625                    ; 4606
	cp $01                          ; 4608  LFO type 1: volume
