	cp $01                          ; 461B
	jr z, .x4654                    ; 461D
	cp $02                          ; 461F
	jr z, .x4673                    ; 4621
	jr .x4680                       ; 4623
.x4625
	ld a, b                         ; 4625
	srl c                           ; 4626
	sub c                           ; 4628
	ld c, a                         ; 4629
	ld a, $00                       ; 462A
	sbc a, a                        ; 462C
	sla c                           ; 462D
	rla                             ; 462F
	sla c                           ; 4630
	rla                             ; 4632
	sla c                           ; 4633
	rla                             ; 4635
	ld b, a                         ; 4636
.x4637
	ld a, c                         ; 4637
	cp [hl]                         ; 4638
	jr z, .x4644                    ; 4639
	ld a, [wTrackFlags]             ; 463B
	set 2, a                        ; 463E
	ld [wTrackFlags], a             ; 4640
	ld [hl], c                      ; 4643
.x4644
	inc hl                          ; 4644
	ld a, b                         ; 4645
	cp [hl]                         ; 4646
	jr z, .x4652                    ; 4647
	ld a, [wTrackFlags]             ; 4649
	set 2, a                        ; 464C
	ld [wTrackFlags], a             ; 464E
	ld [hl], b                      ; 4651
.x4652
	jr .x4680                       ; 4652
.x4654
	ld a, $FF                       ; 4654
	sla b                           ; 4656
	sub b                           ; 4658
	and $F0                         ; 4659
	ld c, a                         ; 465B
	cp [hl]                         ; 465C
	jr z, .x4668                    ; 465D
	ld a, [wTrackFlags]             ; 465F
	set 1, a                        ; 4662
	ld [wTrackFlags], a             ; 4664
	ld [hl], c                      ; 4667
.x4668
	jr .x4680                       ; 4668
.x466A
	ld a, b                         ; 466A
	srl c                           ; 466B
	sub c                           ; 466D
	sla a                           ; 466E
	and $E0                         ; 4670
	ld c, a                         ; 4672
.x4673
	ld a, c                         ; 4673
	cp [hl]                         ; 4674
	jr z, .x4680                    ; 4675
	ld a, [wTrackFlags]             ; 4677
	set 0, a                        ; 467A
	ld [wTrackFlags], a             ; 467C
	ld [hl], c                      ; 467F
.x4680
	ld a, [wCurTrack]               ; 4680
	ld l, a                         ; 4683
	ld a, [wCurTrack+1]             ; 4684
	ld h, a                         ; 4687
	ld a, [wTrackFlags]             ; 4688

