ApplyTrackParams:
	bit 2, a                        ; 468B
	jr z, .x46CB                    ; 468D
	ld bc, $001C                    ; 468F
	add hl, bc                      ; 4692
	ld e, [hl]                      ; 4693
	ld a, $00                       ; 4694
	sla e                           ; 4696
	sbc a, a                        ; 4698
	ld d, a                         ; 4699
	ld bc, $FFFE                    ; 469A
	add hl, bc                      ; 469D
	ld a, [hl+]                     ; 469E
	add a, e                        ; 469F
	ld e, a                         ; 46A0
