	ld bc, $FFF8                    ; 46A4
	add hl, bc                      ; 46A7
	ld a, [hl+]                     ; 46A8
	add a, e                        ; 46A9
	ld e, a                         ; 46AA
	ld a, [hl-]                     ; 46AB
	adc a, d                        ; 46AC
	ld d, a                         ; 46AD
	ld bc, $0010                    ; 46AE
	add hl, bc                      ; 46B1
	ld a, [hl+]                     ; 46B2
	cp $00                          ; 46B3
	jr nz, .x46BD                   ; 46B5
	ld a, [hl+]                     ; 46B7
	add a, e                        ; 46B8
	ld e, a                         ; 46B9
	ld a, [hl-]                     ; 46BA
	adc a, d                        ; 46BB
	ld d, a                         ; 46BC
.x46BD
	ld bc, $0009                    ; 46BD
	add hl, bc                      ; 46C0
	ld a, e                         ; 46C1
	ld [hl+], a                     ; 46C2
	ld [hl], d                      ; 46C3
	ld bc, $FFD3                    ; 46C4
	add hl, bc                      ; 46C7
	ld a, [wTrackFlags]             ; 46C8
.x46CB
	bit 0, a                        ; 46CB
	jr z, .x46EE                    ; 46CD
	ld bc, $0016                    ; 46CF
	add hl, bc                      ; 46D2
	ld a, [hl+]                     ; 46D3
	add a, [hl]                     ; 46D4
	ld e, a                         ; 46D5
	ld bc, $000B                    ; 46D6
	add hl, bc                      ; 46D9
	ld a, [hl+]                     ; 46DA
	cp $02                          ; 46DB
	jr nz, .x46E2                   ; 46DD
	ld a, [hl]                      ; 46DF
	add a, e                        ; 46E0
	ld e, a                         ; 46E1
.x46E2
