	add hl, bc                      ; 46E5
	ld [hl], e                      ; 46E6
	ld bc, $FFD2                    ; 46E7
	add hl, bc                      ; 46EA
	ld a, [wTrackFlags]             ; 46EB
.x46EE
	bit 1, a                        ; 46EE
	jr z, .x4728                    ; 46F0
	ld bc, $0014                    ; 46F2
	add hl, bc                      ; 46F5
