	ld a, [wCurTrack+1]             ; 47AB
	ld h, a                         ; 47AE
	inc hl                          ; 47AF
	ld a, b                         ; 47B0
	ld [hl+], a                     ; 47B1
	ld a, e                         ; 47B2
	ld [hl+], a                     ; 47B3
	ld a, d                         ; 47B4
