	inc a                           ; 47CC
	ld [hl], a                      ; 47CD
	ld c, a                         ; 47CE
	ld b, $00                       ; 47CF
	add hl, bc                      ; 47D1
	ld bc, $000B                    ; 47D2
	add hl, bc                      ; 47D5
	inc de                          ; 47D6
	inc de                          ; 47D7
	ld a, e                         ; 47D8
